    if ((m = core.match(/^(\d+)% · razonable$/))) return ({en:`${m[1]}% · reasonable`,fr:`${m[1]}% · raisonnable`,it:`${m[1]}% · ragionevole`,de:`${m[1]}% · angemessen`,va:`${m[1]}% · raonable`,ca:`${m[1]}% · raonable`,eu:`${m[1]}% · arrazoizkoa`,gl:`${m[1]}% · razoable`})[lang];
