    if ((m = core.match(/^Esquema “(.+)” aplicado\. Solo se han cambiado las posiciones de las mesas\.$/))) return ({en:`“${translateText(m[1],lang)}” layout applied. Only desk positions were changed.`,fr:`Disposition « ${translateText(m[1],lang)} » appliquée. Seules les positions des tables ont changé.`,it:`Schema “${translateText(m[1],lang)}” applicato. Sono cambiate solo le posizioni dei banchi.`,de:`Anordnung „${translateText(m[1],lang)}“ angewendet. Nur die Tischpositionen wurden geändert.`,va:`Esquema «${translateText(m[1],lang)}» aplicat. Només s’han canviat les posicions de les taules.`,ca:`Esquema «${translateText(m[1],lang)}» aplicat. Només s’han canviat les posicions de les taules.`,eu:`“${translateText(m[1],lang)}” antolaketa aplikatu da. Mahaien posizioak bakarrik aldatu dira.`,gl:`Esquema «${translateText(m[1],lang)}» aplicado. Só se cambiaron as posicións das mesas.`})[lang];

